CREATE TABLE IF NOT EXISTS teacher_student_reports(id TEXT PRIMARY KEY,category TEXT NOT NULL,title TEXT NOT NULL,grade TEXT NOT NULL DEFAULT '',studentName TEXT NOT NULL DEFAULT '',violation TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',fileName TEXT NOT NULL DEFAULT '',fileType TEXT NOT NULL DEFAULT '',fileSize INTEGER NOT NULL DEFAULT 0,fileData TEXT NOT NULL DEFAULT '',created TEXT NOT NULL,updated TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0);
